/**
 * TweetCard
 *
 * X-style post card: avatar + name + verified + handle on the left, X logo
 * top-right, tweet text below, footer with comment + heart counter rolls.
 * Card scales in via spring; counters roll up from 0 over the back half.
 *
 * social-tweet.tsx is refactored to consume this primitive; both paths
 * render byte-identical DOM.
 */

import * as React from "react";
import { interpolate, spring, SPRING_SMOOTH } from "../../react-animations/animation-utils";
import { autoTextColor } from "../../scene-templates/color-utils";
import { stripPipe } from "../../scene-templates/text-utils";
import { renderWithEmoji } from "../../emoji/emoji-text";

const CLAMP = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };

const X = {
  cardBg: "#16181c",
  cardBorder: "#2f3336",
  text: "rgb(230, 230, 230)",
  muted: "#71767b",
  verified: "#1d9bf0",
};

export function formatCount(n: number): string {
  // Boundary rule: never let the leading number reach 4 digits — promote
  // to the next unit. Without this, 999,999 likes rounded to "1000K"
  // (mathematically right but breaks the K-suffix convention). Each
  // branch double-checks the rounded value: if rounding would push it
  // ≥1000, fall through to the next unit so 999,500 ≤ n < 1,000,000
  // displays as "1M" not "1000K".
  const abs = Math.abs(n);
  const sign = n < 0 ? "-" : "";
  if (abs < 1_000) return n.toLocaleString();
  if (abs < 10_000) {
    const v = abs / 1_000;
    const rounded = Number(v.toFixed(1));
    if (rounded < 10) return `${sign}${rounded.toString().replace(/\.0$/, "")}K`;
    // falls through to the integer-K branch
  }
  if (abs < 1_000_000) {
    const k = Math.round(abs / 1_000);
    if (k < 1_000) return `${sign}${k}K`;
    // falls through to M
  }
  if (abs < 10_000_000) {
    const v = abs / 1_000_000;
    const rounded = Number(v.toFixed(1));
    if (rounded < 10) return `${sign}${rounded.toString().replace(/\.0$/, "")}M`;
  }
  if (abs < 1_000_000_000) {
    const m = Math.round(abs / 1_000_000);
    if (m < 1_000) return `${sign}${m}M`;
  }
  const v = abs / 1_000_000_000;
  return `${sign}${v.toFixed(1).replace(/\.0$/, "")}B`;
}

export function hashHue(str: string): number {
  let h = 0;
  for (let i = 0; i < str.length; i++) h = (h * 31 + str.charCodeAt(i)) % 360;
  return h;
}

export function deriveHandle(brandName: string): string {
  const slug = brandName.toLowerCase().replace(/[^a-z0-9]/g, "");
  return slug ? `@${slug}` : "";
}

const XLogo: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 1200 1227" fill="none">
    <path
      d="M714.163 519.284 1160.89 0h-105.86L667.137 450.887 357.328 0H0l468.492 681.821L0 1226.37h105.866l409.625-476.152 327.181 476.152H1200L714.137 519.284h.026ZM569.165 687.828l-47.468-67.894-377.686-540.24h162.604l304.797 435.991 47.468 67.894 396.2 566.721H892.476L569.165 687.854v-.026Z"
      fill={X.text}
    />
  </svg>
);

const VerifiedBadge: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 22 22" fill="none">
    <path
      d="M20.396 11c-.018-.646-.215-1.275-.57-1.816-.354-.54-.852-.972-1.438-1.246.223-.607.27-1.264.14-1.897-.131-.634-.437-1.218-.882-1.687-.47-.445-1.053-.75-1.687-.882-.633-.13-1.29-.083-1.897.14-.273-.587-.704-1.086-1.245-1.44C12.276 1.819 11.647 1.62 11 1.604c-.646.017-1.273.213-1.813.568s-.969.854-1.24 1.44c-.608-.223-1.267-.272-1.902-.14-.635.13-1.22.436-1.69.882-.445.47-.749 1.055-.878 1.688-.13.633-.08 1.29.144 1.896-.587.274-1.087.705-1.443 1.245-.356.54-.555 1.17-.574 1.817.02.647.218 1.276.574 1.817.356.54.856.972 1.443 1.245-.224.606-.274 1.263-.144 1.896.13.634.433 1.218.877 1.688.47.443 1.054.747 1.687.878.633.132 1.29.084 1.897-.136.274.586.705 1.084 1.246 1.439.54.354 1.17.551 1.816.569.647-.016 1.276-.213 1.817-.567s.972-.854 1.245-1.44c.604.239 1.266.296 1.903.164.636-.132 1.22-.447 1.68-.907.46-.46.776-1.044.908-1.681s.075-1.299-.165-1.903c.586-.274 1.084-.705 1.439-1.246.354-.54.551-1.17.569-1.816zM9.662 14.85L6.8 12.46l1.41-1.42 2.262 2.26 4.798-5.23 1.47 1.36-6.198 6.77z"
      fill={X.verified}
    />
  </svg>
);

const CommentIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={X.muted} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
    <path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z" />
  </svg>
);

const HeartIcon: React.FC<{ size: number }> = ({ size }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke={X.muted} strokeWidth={1.8} strokeLinecap="round" strokeLinejoin="round">
    <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z" />
  </svg>
);

// ─── Typed component (direct use from templates) ────────────────

export interface TweetCardProps {
  progress: number;
  authorName: string;
  authorHandle?: string;
  authorVerified?: boolean;
  message: string;
  /** Decorative engagement counter. Default 0 (counter just rolls to 0). */
  targetLikes?: number;
  /** Decorative engagement counter. Default 0. */
  targetReplies?: number;
  /** Avatar background tint (defaults to hashed hue of authorName) */
  accent?: string;
  width: number;
  height: number;
  beatIntensity?: number;
}

export const TweetCard: React.FC<TweetCardProps> = ({
  progress,
  authorName: rawName,
  authorHandle: rawHandle,
  authorVerified,
  message: rawMessage,
  targetLikes = 0,
  targetReplies = 0,
  accent,
  width,
  height,
  beatIntensity = 0,
}) => {
  const dim = Math.min(width, height);
  const s = dim / 1080;
  const resolvedAccent = accent || `hsl(${hashHue(String(rawName))}, 60%, 55%)`;

  const authorName = stripPipe(rawName);
  const customHandle = stripPipe(rawHandle || "").trim();
  const authorHandle = customHandle || deriveHandle(authorName);
  const isVerified = authorVerified !== false;
  const message = stripPipe(rawMessage);

  const initialChar = authorName.charAt(0).toUpperCase() || "•";

  const cardScale = spring(interpolate(progress, [0, 0.24], [0, 1], CLAMP), SPRING_SMOOTH);
  const cardOpacity = interpolate(progress, [0, 0.18], [0, 1], CLAMP);
  const replyCount = Math.round(interpolate(progress, [0.30, 0.75], [0, targetReplies], CLAMP));
  const likeCount = Math.round(interpolate(progress, [0.35, 0.80], [0, targetLikes], CLAMP));
  const beatScale = 1 + beatIntensity * 0.01;

  const cardWidth = Math.min(width * 0.92, dim * 0.95);
  const cardPad = dim * 0.05;
  const cardRadius = dim * 0.026;
  const avatarSize = dim * 0.09;
  const xLogoSize = dim * 0.072;
  const verifiedSize = dim * 0.028;
  const nameFontSize = dim * 0.04;
  const handleFontSize = dim * 0.030;
  const messageFontSize = dim * 0.046;
  const footerIconSize = dim * 0.032;
  const footerFontSize = dim * 0.030;
  const headerToBodyGap = dim * 0.028;
  const bodyToFooterGap = dim * 0.032;

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <div
        style={{
          width: cardWidth,
          backgroundColor: X.cardBg,
          borderRadius: cardRadius,
          padding: cardPad,
          border: `1px solid ${X.cardBorder}`,
          boxShadow: [
            `0 ${1 * s}px ${3 * s}px 0 rgba(0,0,0,0.1)`,
            `0 ${1 * s}px ${2 * s}px ${-1 * s}px rgba(0,0,0,0.1)`,
            `0 ${20 * s}px ${60 * s}px rgba(0,0,0,0.45)`,
          ].join(", "),
          opacity: cardOpacity,
          transform: `scale(${cardScale * beatScale})`,
        }}
      >
        <div style={{ display: "flex", alignItems: "center", gap: dim * 0.018 }}>
          <div
            style={{
              width: avatarSize,
              height: avatarSize,
              borderRadius: "50%",
              flexShrink: 0,
              overflow: "hidden",
              backgroundColor: resolvedAccent,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <span style={{ color: autoTextColor(resolvedAccent), fontSize: avatarSize * 0.46, fontWeight: 700, letterSpacing: -0.5, lineHeight: 1 }}>
              {initialChar}
            </span>
          </div>

          <div style={{ display: "flex", flexDirection: "column", flex: 1, minWidth: 0, gap: dim * 0.002 }}>
            <div style={{ display: "flex", alignItems: "center", gap: dim * 0.006 }}>
              <span style={{ color: X.text, fontSize: nameFontSize, fontWeight: 700, letterSpacing: -0.3, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
                {authorName}
              </span>
              {isVerified && <VerifiedBadge size={verifiedSize} />}
            </div>
            <span style={{ color: X.muted, fontSize: handleFontSize, fontWeight: 400, lineHeight: 1.1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
              {authorHandle}
            </span>
          </div>

          <div style={{ flexShrink: 0 }}>
            <XLogo size={xLogoSize} />
          </div>
        </div>

        <div style={{ color: X.text, fontSize: messageFontSize, lineHeight: 1.4, letterSpacing: -0.1, marginTop: headerToBodyGap, wordBreak: "break-word" }}>
          {renderWithEmoji(message, messageFontSize)}
        </div>

        <div style={{ display: "flex", alignItems: "center", gap: dim * 0.04, marginTop: bodyToFooterGap }}>
          <div style={{ display: "flex", alignItems: "center", gap: dim * 0.008 }}>
            <CommentIcon size={footerIconSize} />
            <span style={{ color: X.muted, fontSize: footerFontSize, fontVariantNumeric: "tabular-nums" }}>{formatCount(replyCount)}</span>
          </div>
          <div style={{ display: "flex", alignItems: "center", gap: dim * 0.008 }}>
            <HeartIcon size={footerIconSize} />
            <span style={{ color: X.muted, fontSize: footerFontSize, fontVariantNumeric: "tabular-nums" }}>{formatCount(likeCount)}</span>
          </div>
        </div>
      </div>
    </div>
  );
};

/**
 * EmojiText / renderWithEmoji — split a string into text runs + color-emoji
 * runs, rendering each color emoji as an inline emoji-PNG <img> (via <Emoji>)
 * while leaving everything else as plain text.
 *
 * Why this exists: raw-unicode emoji fall through to the OS emoji font (Mac =
 * Apple, Linux = Noto), so the three render paths (preview / client SVG export
 * / server Puppeteer) disagree. Wrapping every template/AI-supplied string here
 * makes ALL color emoji render as the same mapped PNG in all three.
 *
 * What it does NOT touch: monochrome symbols (★ ✦ ✓ → ↑ …). Those render
 * identically as text across OSes, and imaging them would be wrong. The gate
 * is `emojiToDataUri()` — only clusters that resolve to a PNG in the
 * map become <img>; anything else (monochrome symbols, unmapped/custom
 * emoji, skin-tone variants not in the set) stays raw text.
 *
 * Segmentation: grapheme clusters via Intl.Segmenter so ZWJ sequences
 * (👩‍💻) and skin-tone modifiers (👍🏽) stay single units. Adjacent emoji
 * clusters each render as their own <img> in sequence.
 *
 * Sizing: each emoji <img> is sized to `fontSizePx` (the surrounding font
 * size) so the emoji box matches a glyph box — width/line-count stay
 * ~identical to the raw-text layout, which keeps fitTextSize / archetype
 * char-count measurement valid (all string-based, never DOM-measured).
 */

import * as React from "react";
import { Emoji, emojiToDataUri } from "./index";

// Coarse "is this cluster a color-emoji candidate?" test. Deliberately broad:
// the real decision is whether emojiToDataUri() resolves it to a mapped PNG.
// This regex only needs to (a) catch the OS-divergent color ranges and (b)
// avoid flagging plain text/whitespace so we don't merge text into emoji runs.
//
//  - \u{1F000}-\u{1FAFF}  — main emoji planes (most pictographs)
//  - \u{2600}-\u{27BF}    — misc symbols + dingbats (color when + FE0F)
//  - \u{2B00}-\u{2BFF}    — stars/arrows block (⭐ lives here)
//  - \u{1F1E6}-\u{1F1FF}  — regional indicators (flags)
//  - \u{1F3FB}-\u{1F3FF}  — skin-tone modifiers
//  - \u{FE0F} | \u{200D} | \u{20E3} — VS16 / ZWJ / keycap combiners
//
// Combining/joiner codepoints (FE0F, ZWJ, keycap) are matched via alternation
// rather than inside the character class — eslint's
// no-misleading-character-class flags combining chars inside `[...]`, and
// alternation is equivalent here (we only test, never capture).
const EMOJI_CANDIDATE =
  /[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{2B00}-\u{2BFF}\u{1F1E6}-\u{1F1FF}]|[\u{1F3FB}-\u{1F3FF}]|\u{FE0F}|\u{200D}|\u{20E3}/u;

function isEmojiCandidate(cluster: string): boolean {
  return EMOJI_CANDIDATE.test(cluster);
}

/** Split text into grapheme clusters (ZWJ + skin-tone safe). */
function toGraphemes(text: string): string[] {
  const Seg = (Intl as unknown as { Segmenter?: typeof Intl.Segmenter }).Segmenter;
  if (Seg) {
    const seg = new Seg(undefined, { granularity: "grapheme" });
    const out: string[] = [];
    for (const { segment } of seg.segment(text)) out.push(segment);
    return out;
  }
  // Fallback: code-point spread. Won't keep ZWJ/skin-tone as single units, so
  // those land as separate clusters; emojiToDataUri's FE0F tolerance + the raw
  // fallback keep them from breaking. Modern browsers all have Segmenter.
  return Array.from(text);
}

export interface RenderWithEmojiOptions {
  /** vertical-align passed to each <Emoji>. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra style merged onto each emoji <img>. */
  emojiStyle?: React.CSSProperties;
}

/**
 * Split `text` into an array of React nodes — plain-text strings interleaved
 * with <Emoji> images for every mapped color emoji. Returns a single-element
 * `[text]` fast-path when there are no color emoji (the common case), so
 * non-emoji text pays ~one regex test.
 *
 * @param text         the string to render
 * @param fontSizePx   surrounding font size in px (emoji box = this size)
 */
export function renderWithEmoji(
  text: string,
  fontSizePx: number,
  opts?: RenderWithEmojiOptions,
): React.ReactNode[] {
  if (!text) return [text];
  // Cheap bail-out: if the whole string has no emoji-range codepoint, return
  // it untouched (no segmentation, no array churn) — the hot path for the vast
  // majority of titles/bodies.
  if (!EMOJI_CANDIDATE.test(text)) return [text];

  const clusters = toGraphemes(text);
  const nodes: React.ReactNode[] = [];
  let textBuf = "";
  let key = 0;

  const flushText = () => {
    if (textBuf) {
      nodes.push(textBuf);
      textBuf = "";
    }
  };

  for (const cluster of clusters) {
    const uri = isEmojiCandidate(cluster) ? emojiToDataUri(cluster) : null;
    if (uri) {
      flushText();
      nodes.push(
        <Emoji
          key={`e${key++}`}
          char={cluster}
          size={fontSizePx}
          verticalAlign={opts?.verticalAlign}
          style={opts?.emojiStyle}
        />,
      );
    } else {
      textBuf += cluster;
    }
  }
  flushText();
  return nodes;
}

/**
 * Per-code-unit emoji plan for the typewriter archetype, which reveals text
 * one UTF-16 code unit at a time and indexes by `text.length`. We can't just
 * call renderWithEmoji there (it would re-segment and desync the visibleChars
 * counter), so this maps each cluster's START code-unit index to its emoji-PNG
 * data URI and marks the cluster's CONTINUATION indices as covered (render
 * nothing for them — the start index's <img> already spans the whole cluster).
 *
 * Returns null when the text contains no mapped color emoji (the common case),
 * so the typewriter render keeps its plain per-char path.
 */
export interface EmojiTypewriterPlan {
  /** code-unit index → full emoji cluster char (cluster start). */
  starts: Map<number, string>;
  /** code-unit indices that are continuations of a cluster (render nothing). */
  covered: Set<number>;
}

export function planTypewriterEmoji(text: string): EmojiTypewriterPlan | null {
  if (!text || !EMOJI_CANDIDATE.test(text)) return null;
  const starts = new Map<number, string>();
  const covered = new Set<number>();
  let idx = 0;
  let found = false;
  for (const cluster of toGraphemes(text)) {
    const len = cluster.length; // UTF-16 code units
    if (isEmojiCandidate(cluster) && emojiToDataUri(cluster)) {
      found = true;
      // Store the WHOLE cluster char (not just the start unit) so callers can
      // pass it straight to <Emoji> for a correct map lookup.
      starts.set(idx, cluster);
      for (let k = 1; k < len; k++) covered.add(idx + k);
    }
    idx += len;
  }
  return found ? { starts, covered } : null;
}

export interface EmojiTextProps {
  /** The text to render, color emoji replaced with emoji-PNG <img>. */
  children: string;
  /** Surrounding font size in px — sizes each emoji image to match a glyph. */
  fontSize: number;
  verticalAlign?: React.CSSProperties["verticalAlign"];
  emojiStyle?: React.CSSProperties;
}

/**
 * Inline wrapper around renderWithEmoji. Renders a React.Fragment of text +
 * emoji <img> runs. Use where a component currently renders a raw `{text}`
 * child and you have the surrounding font size in px.
 */
export const EmojiText: React.FC<EmojiTextProps> = ({
  children,
  fontSize,
  verticalAlign,
  emojiStyle,
}) => {
  const text = typeof children === "string" ? children : "";
  return <>{renderWithEmoji(text, fontSize, { verticalAlign, emojiStyle })}</>;
};

/**
 * Emoji — render emojis as inline PNG data-URI <img> elements.
 *
 * Why images, not the system emoji font: VanillaSky renders the same scene
 * three ways — real-DOM preview, client SVG-as-image export, server Puppeteer.
 * Raw-unicode emojis fall through to whatever emoji font the OS has (Mac=Apple,
 * Linux=Noto), so preview and export disagree. Inlining each emoji as a
 * data-URI <img> renders the SAME PNG in all three. Critically, the
 * client export rasterizes the frame via <img src="data:image/svg+xml">, which
 * can ONLY load inlined data-URI images (not @font-face, not external URLs) —
 * so data URIs are exactly what works there.
 *
 * Source artwork: emoji-datasource-google (Google Noto emoji set, Apache-2.0).
 * The map ships inside the publicly redistributed skill tarball, and Apple's
 * artwork is not licensed for redistribution — Noto's Apache-2.0 is. The set
 * is swappable via the generator's EMOJI_SET constant
 * (scripts/generate-emoji-map.mjs).
 *
 * Bundle: the generated char→dataURI map is ~1.1MB of base64, so it is
 * LAZY-LOADED via dynamic import and never enters the initial app bundle. The
 * import is kicked off eagerly at module load (below) — long before any export
 * or screenshot — so by the time a frame is captured the map has resolved.
 * Until it resolves, <Emoji> renders the raw unicode char, then re-renders to
 * the image when the map lands. Any emoji not in the map also falls back to the
 * raw char, so nothing ever breaks for custom/unmapped emojis.
 */

import * as React from "react";

let EMOJI_MAP: Record<string, string> | null = null;
let loadPromise: Promise<Record<string, string>> | null = null;
const subscribers = new Set<() => void>();

function loadEmojiMap(): Promise<Record<string, string>> {
  if (loadPromise) return loadPromise;
  loadPromise = import("./emoji-map.generated")
    .then((mod) => {
      EMOJI_MAP = mod.default;
      subscribers.forEach((fn) => fn());
      return EMOJI_MAP;
    })
    .catch((err) => {
      // Network/chunk failure: leave map null → everything falls back to char.
      console.warn("[emoji] failed to load emoji map:", err);
      EMOJI_MAP = {};
      return EMOJI_MAP;
    });
  return loadPromise;
}

// Kick off the load immediately when this module is first imported (app/registry
// init), so the map is ready well before any export or server screenshot.
loadEmojiMap();

/**
 * Resolve once the emoji-PNG map has loaded (or definitively failed). Render
 * paths that capture frames MUST await this before their first capture so they
 * never screenshot a frame while emoji are still raw-unicode chars:
 *   - server: Render.tsx awaits before setting window.__ready
 *   - client export: export-video.ts awaits in the media-preload step
 * The preview path doesn't capture, so it can stay lazy (subscribers re-render
 * char → image when the map lands). On chunk failure this resolves to {} so
 * the await never hangs — everything falls back to the raw char.
 */
export function ensureEmojiMap(): Promise<Record<string, string>> {
  return loadEmojiMap();
}

/**
 * Returns the emoji-PNG data URI for an emoji char, or null if the map hasn't
 * loaded yet or the char isn't in the set (caller should fall back to the char).
 */
export function emojiToDataUri(char: string): string | null {
  if (!EMOJI_MAP) return null;
  const key = (char || "").trim();
  if (EMOJI_MAP[key]) return EMOJI_MAP[key];
  // Tolerate a trailing variation selector mismatch (U+FE0F).
  const stripped = key.replace(/️/g, "");
  if (stripped !== key && EMOJI_MAP[stripped]) return EMOJI_MAP[stripped];
  return null;
}

/** Subscribe to map-loaded so a component re-renders char → image when ready. */
function useEmojiMapReady(): boolean {
  const [, force] = React.useReducer((n: number) => n + 1, 0);
  React.useEffect(() => {
    if (EMOJI_MAP) return;
    const fn = () => force();
    subscribers.add(fn);
    loadEmojiMap();
    return () => {
      subscribers.delete(fn);
    };
  }, []);
  return EMOJI_MAP != null;
}

export interface EmojiProps {
  /** The emoji character(s), e.g. "🎉". */
  char: string;
  /** Box size in px — matches the prior glyph's font-size so layout is identical. */
  size: number;
  /** vertical-align for inline flow. Defaults to a glyph-like baseline nudge. */
  verticalAlign?: React.CSSProperties["verticalAlign"];
  /** Extra styles merged onto the <img> (or fallback <span>). */
  style?: React.CSSProperties;
}

/**
 * Renders an emoji as an inline emoji-PNG <img> when available, else the raw
 * unicode char in a same-size box (so scale/opacity/transform are unchanged).
 */
export const Emoji: React.FC<EmojiProps> = ({ char, size, verticalAlign = "-0.15em", style }) => {
  useEmojiMapReady();
  const uri = emojiToDataUri(char);

  if (!uri) {
    // Fallback: raw char sized to the same box so layout/scale are preserved.
    return (
      <span
        style={{
          fontSize: size,
          lineHeight: 1,
          display: "inline-block",
          ...style,
        }}
      >
        {char}
      </span>
    );
  }

  return (
    <img
      src={uri}
      alt={char}
      width={size}
      height={size}
      style={{
        width: size,
        height: size,
        objectFit: "contain",
        display: "inline-block",
        verticalAlign,
        ...style,
      }}
    />
  );
};

/**
 * Color utilities for scene templates.
 *
 * Provides safe color manipulation that works with hex colors
 * and graceful fallbacks for non-hex inputs.
 */
import React from "react";
import type { GlobalStyle } from "../video-config";
import { resolveTokens } from "./tokens";

// ─── Layout constants ───────────────────────────────────────
//
// Shared vertical layout for templates that place a TextOverlay at the top of
// the scene (showcase-*, chart-*, infographic-*). Using a single constant
// guarantees the headline sits in the same place across every template, so
// scene-to-scene cuts don't visually jump.
//
// TextOverlay vertically centers itself inside its container, so the visual
// midline of the headline = TOP_TEXT_AREA_RATIO / 2 of the scene height.
export const TOP_TEXT_AREA_RATIO = 0.32;

/**
 * Convert a hex color + opacity (0-1) to an rgba() string.
 * Handles 3-digit (#abc) and 6-digit (#aabbcc) hex.
 * Falls back to the raw color with opacity if not parseable as hex.
 */
export function withOpacity(hex: string, opacity: number): string {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return hex; // Not hex — return as-is

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return hex;
  }

  return `rgba(${r},${g},${b},${opacity})`;
}

/**
 * Check if a hex color is dark (luminance < 0.5).
 * Uses relative luminance formula from WCAG.
 */
export function isColorDark(hex: string): boolean {
  const match = hex.match(/^#([0-9a-f]{3,8})$/i);
  if (!match) return true; // Default to dark if not parseable

  let r: number, g: number, b: number;
  const h = match[1];

  if (h.length === 3) {
    r = parseInt(h[0] + h[0], 16);
    g = parseInt(h[1] + h[1], 16);
    b = parseInt(h[2] + h[2], 16);
  } else if (h.length >= 6) {
    r = parseInt(h.slice(0, 2), 16);
    g = parseInt(h.slice(2, 4), 16);
    b = parseInt(h.slice(4, 6), 16);
  } else {
    return true;
  }

  // Relative luminance (simplified sRGB)
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance < 0.5;
}

/**
 * Given two colors, return them ordered [darker, lighter] by relative
 * luminance. Used by gradient backgrounds so the darker stop always anchors
 * the top of the frame.
 */
export function orderDarkToLight(a: string, b: string): [string, string] {
  const lum = (hex: string): number => {
    const m = hex.match(/^#([0-9a-f]{6})$/i);
    if (!m) return 0;
    const h = m[1];
    const r = parseInt(h.slice(0, 2), 16);
    const g = parseInt(h.slice(2, 4), 16);
    const b2 = parseInt(h.slice(4, 6), 16);
    return 0.299 * r + 0.587 * g + 0.114 * b2;
  };
  return lum(a) <= lum(b) ? [a, b] : [b, a];
}

/**
 * Auto-derive text color from background color.
 * Returns white for dark backgrounds, near-black for light ones.
 */
export function autoTextColor(bg: string): string {
  return isColorDark(bg) ? "#ffffff" : "#111111";
}

/**
 * Shift a hex color's hue by a number of degrees — canonical implementation
 * lives with the token resolver; re-exported here because every template
 * historically imports it from color-utils.
 */
export { shiftHue } from "./tokens";

/**
 * Gradient background — clean 2-color linear gradient with a subtle
 * animated breathing overlay. Matches the look of a plain CSS
 * `linear-gradient(90deg, colorA, colorB)` so palette chips preview
 * exactly what templates render.
 *
 * The animation is deliberately minimal: two low-opacity radial blobs
 * of the same two colors drift slowly, adding just enough motion for
 * video without introducing a third "midtone" color that muddies
 * the gradient (a common source of unwanted purple/brown tints).
 */
export function gradientBackground({
  colorA,
  colorB,
  solidBg,
  progress,
  sceneDuration,
  seed,
}: {
  colorA: string;
  colorB: string;
  /**
   * When set, the function returns this color as a solid background
   * (no gradient, no animated radial overlays). Used when the user has
   * a scraped brand whose darkest color reads as a real surface — the
   * accent stays on text/CTAs, but the bg goes flat instead of pairing
   * with an unrelated brand color and producing a noisy gradient.
   */
  solidBg?: string;
  progress: number;
  sceneDuration?: number;
  seed: number;
}): string {
  if (solidBg) return solidBg;
  const elapsed = progress * (sceneDuration || 3);
  const t = elapsed * 0.6;

  const seededRandom = (s: number): number => {
    const x = Math.sin(s * 12.9898 + s * 78.233) * 43758.5453;
    return x - Math.floor(x);
  };
  const phase = seededRandom(seed) * Math.PI * 2;

  const x1 = 25 + Math.sin(t + phase) * 25;
  const y1 = 30 + Math.cos(t * 0.7 + phase + 1.0) * 25;
  const x2 = 75 + Math.sin(t * 0.6 + phase + 2.0) * 25;
  const y2 = 70 + Math.cos(t * 0.4 + phase + 3.5) * 25;

  // Darker of the two colors anchors the top of the frame so text and logos
  // sit over the stronger value. 180deg = top→bottom.
  const [topColor, bottomColor] = orderDarkToLight(colorA, colorB);

  return `
    radial-gradient(ellipse 60% 60% at ${x1}% ${y1}%, ${colorA}4d 0%, transparent 65%),
    radial-gradient(ellipse 60% 60% at ${x2}% ${y2}%, ${colorB}4d 0%, transparent 65%),
    linear-gradient(180deg, ${topColor} 0%, ${bottomColor} 100%)
  `;
}

/**
 * Animated brand-gradient overlay. Drop as the first child inside a template's
 * outer container. Uses accent + secondary (or hue-shifted accent) as gradient
 * colors. When the user is in solid mode (accent = secondary = bg), the
 * gradient collapses to a flat layer — no visual effect beyond the solid bg.
 */
export const BrandGradientOverlay: React.FC<{
  style: GlobalStyle;
  progress: number;
  sceneDuration?: number;
  seed: number;
}> = ({ style: globalStyle, progress, sceneDuration, seed }) => {
  const tokens = resolveTokens(globalStyle);
  const accent = tokens.accent;
  // tokens.secondary carries the "auto" guard: an explicit kit secondary
  // passes through verbatim, but the literal string "auto" (the kit's
  // derive-for-me sentinel) resolves to shiftHue(accent, 50) instead of
  // leaking into the CSS gradient as an invalid color.
  const secondary = tokens.secondary;
  const solidBg = tokens.bg;

  return React.createElement("div", {
    style: {
      position: "absolute" as const,
      inset: 0,
      background: gradientBackground({ colorA: accent, colorB: secondary, solidBg, progress, sceneDuration, seed }),
      pointerEvents: "none" as const,
    },
  });
};

/**
 * VideoConfig — React template-based architecture.
 *
 * Every scene is a React template. Templates declare their variables via a schema,
 * and the Studio auto-generates input UI from it. AI picks templates by matching
 * descriptions to the user's prompt.
 */

// ─── Orientation & Dimensions ──────────────────────────────────

export type Orientation = "portrait" | "landscape";

export interface VideoDimensions {
  width: number;
  height: number;
  aspectRatio: string;
}

export interface SafeZone {
  top: number;
  bottom: number;
  left: number;
  right: number;
}

export function getDimensions(orientation: Orientation = "portrait"): VideoDimensions {
  return orientation === "landscape"
    ? { width: 1920, height: 1080, aspectRatio: "16 / 9" }
    : { width: 1080, height: 1920, aspectRatio: "9 / 16" };
}

export function getSafeZone(orientation: Orientation = "portrait"): SafeZone {
  return orientation === "landscape"
    ? { top: 108, bottom: 108, left: 192, right: 192 }    // SMPTE broadcast safe (10%)
    : { top: 100, bottom: 100, left: 60, right: 60 };     // Balanced safe zone — enough margin without eating content
}

// ─── Core Config ───────────────────────────────────────────────

export interface VideoConfig {
  orientation?: Orientation;
  audio?: AudioConfig;
  scenes: SceneConfig[];
  style: GlobalStyle;
  meta?: VideoMeta;
}

// ─── Audio ─────────────────────────────────────────────────────

export interface AudioConfig {
  trackId: string;
  audioUrl: string;
  duration: number;
  beatDetection: BeatDetectionConfig;
  beatMarkers: BeatMarker[];
  /** Volume 0.0-1.0. Default 1.0 (full track volume). */
  volume?: number;
  /** Fade-out duration in milliseconds at end of audio. When unset, falls
   *  back to min(lastSceneDuration, 3s) via `defaultFadeOutMs()` — the fade
   *  ramps down over the closer instead of cutting hard. Set explicitly
   *  (including 0) to override. */
  fadeOutMs?: number;
}

export interface BeatDetectionConfig {
  sensitivity: number;
  targetBeats?: number;
  minInterval?: number;
}

export interface BeatMarker {
  time: number;
  manual?: boolean;
  energy?: "high" | "medium" | "low";
}

// ─── Scene ─────────────────────────────────────────────────────

export interface SceneConfig {
  id: string;
  templateId: string;
  variables: Record<string, unknown>;
  /** Text archetype for this scene. One of the 6 names in TEXT_ARCHETYPES. */
  textArchetype?: string;
  // Note: scene-level transition override (formerly `transition?: string` with
  // a UI selector for crossfade / cut / slide / flash / dip / zoom) was
  // removed when none of the eight options were wired to the renderer.
  // Renderer now picks cut vs dissolve from `shouldDissolveBetween` in
  // scene-resolver.ts. Re-introduce as `transition: "cut" | "dissolve"` here
  // if real exceptions to the continuity rule appear.
  /** Override video-level default background effect (for templates that opt in) */
  backgroundEffect?: string;
  /**
   * Per-scene background override. When set, this scene renders on the
   * overridden gradient (accent + secondary) instead of the video-level
   * brand. Solid mode = accent equals secondary; gradient = distinct.
   */
  backgroundOverride?: { accent: string; secondary: string };
  timing: TimingConfig;
  /** AI-generated alternative templates with purpose-written copy. 0–3 per scene. */
  alternatives?: AlternativeTemplate[];
  /**
   * Raw React source for vibecoded (custom_*) templates. Set on save so
   * server-side render (`/render` + Trigger.dev export) can rehydrate the
   * template without the client's sessionStorage. Empty for built-in
   * templates. Stripped before display — never read at runtime in the Studio
   * (the in-memory `customTemplates` registry is the source of truth there).
   */
  componentSource?: string;
}

// ─── Alternative Template ─────────────────────────────────────

export interface AlternativeTemplate {
  templateId: string;
  variables: Record<string, unknown>;
  /** Human-readable rationale shown in the picker (e.g. "More cinematic", "Social proof angle") */
  rationale?: string;
}

// ─── Variable Schema ──────────────────────────────────────────

export interface VariableField {
  type: "string" | "number" | "boolean" | "enum" | "media" | "color" | "data-points";
  label: string;
  default?: unknown;
  /** Options for enum type */
  options?: string[];
  required?: boolean;
  /** Help text shown in Studio and used by AI for context */
  description?: string;
}

// ─── Timing ────────────────────────────────────────────────────

export interface TimingConfig {
  beatStart?: number;           // beat marker index (beat-sync mode)
  beatEnd?: number;             // beat marker index (beat-sync mode)
  startTime?: number;           // seconds (time-based mode)
  endTime?: number;             // seconds (time-based mode)
  fixedDuration?: number;       // seconds (no-audio mode)
  durationWeight?: number;      // relative weight for auto-distribution
}

// ─── Style ─────────────────────────────────────────────────────

export interface GlobalStyle {
  font: string;
  brandKit?: BrandKit;
  /** Default text archetype when a scene doesn't set one. */
  defaultTextArchetype?: string;
  /** Default transition between scenes */
  defaultTransition?: string;
  /** Default background effect — consumed by templates with usesGlobalBackgroundEffect: true */
  defaultBackgroundEffect?: string;
}

// ─── Brand Kit ────────────────────────────────────────────────

export interface BrandKit {
  /** Primary brand color — drives one half of the gradient mesh and most accents. */
  accent: string;
  /** Secondary brand color — drives the other half of the gradient mesh.
   *  When equal to accent, the gradient collapses to a flat color (solid mode). */
  secondary?: string;
  /** Optional explicit text color override — defaults to white (#ffffff) when
   *  not set. Templates render scrims/vignettes to handle bright surfaces. */
  text?: string;
  logoDataUrl?: string;
  /**
   * Solid scene background override. When set, the gradient renderer
   * collapses to this single color — use it when the brand has a clear dark
   * surface (e.g., dark body text on a light marketing page reads as a real
   * navy / charcoal brand color). Pairing it with `accent` in a gradient
   * produces muddy results, so anchor the bg flat and let `accent` handle
   * highlights.
   */
  bg?: string;
  /**
   * Normalized URL the brand kit was derived from, when it came from a URL
   * rather than being set explicitly. Acts as a cache key: a later config
   * pointing at the same URL can reuse the kit instead of re-deriving it.
   */
  sourceUrl?: string;

  // ─── Extended fields for primitive composition ────────────────────
  /** Deepest background surface — defaults to a near-black if unset. */
  surface?: string;
  /** Elevated card / panel surface — defaults to surface + 4% lighten. */
  surface_elevated?: string;
  /** Muted text color for labels, footers, supporting copy. Default #a7a6b0. */
  muted?: string;
  /** Script accent font family for handwritten callouts (Caveat-style). Default "Caveat". */
  script_font?: string;
  /** Inferred mood/vibe from URL capture — used downstream for music selection. */
  vibe?: "default" | "reflective" | "edgy" | "playful" | "premium";
}

// ─── Gradient / Background Style (used by VideoManager, VideoCardPreview, BackgroundShowcase for saved videos) ──

export type BackgroundStyle = "solid" | "blobs" | "waves" | "blurry-gradient" | "circles" | "blob-scene" | "layered-waves" | "stacked-waves" | "blob-scatter" | "polygon-scatter" | "symbol-scatter" | "radial-gradient" | "mesh-gradient" | (string & {});

export interface PatternParams {
  complexity?: number;
  contrast?: number;
  size?: number;
  count?: number;
  balance?: number;
  variant?: "solid" | "outline";
  direction?: "up" | "down" | "left" | "right";
}

export interface GradientConfig {
  colors: [string, string];
  style: BackgroundStyle;
  animationSpeed: number;
  params?: PatternParams;
}

// ─── Meta ──────────────────────────────────────────────────────

export interface VideoMeta {
  name?: string;
  prompt?: string;
  sourceUrl?: string;
  createdAt?: string;
  mood?: string[];
  videoType?: string;
  /** Video format. Currently only "launch"; grows as new formats ship (review, milestone, etc.). */
  format?: "launch";
  trackRationale?: string;
  templateRationale?: string;
  source?: string;
  uploadedMediaUrls?: string[];
  /** Flat list of images the user uploaded on the landing page. The chat
   *  routes them to scenes via vision + setSceneMedia on turn 0. */
  uploadedImages?: string[];
  documentContent?: string;
  /** Stable identifier for the studio chat thread tied to this config.
   *  Lazily assigned the first time the user opens the chat, persisted via
   *  the same localStorage path as the rest of the config so the chat
   *  history (kept in sessionStorage under this key) can be rehydrated
   *  across tab switches and page reloads within a session. */
  chatId?: string;
  /** The `shared_configs` row this video is persisted to. Stamped when a
   *  config loads from `?config=<id>` and on the first autosave/export of a
   *  new build. Anchors continuous autosave + export to a single row
   *  (update-in-place) instead of minting a new row per save. */
  savedConfigId?: string;
  /** Stamped server-side by save-config when markExported is passed. */
  exported_at?: string;
}

// ─── Validation ────────────────────────────────────────────────

export function validateVideoConfig(config: unknown): config is VideoConfig {
  if (!config || typeof config !== "object") return false;
  const c = config as Record<string, unknown>;

  if (!Array.isArray(c.scenes) || c.scenes.length === 0) return false;
  if (!c.style || typeof c.style !== "object") return false;

  const style = c.style as Record<string, unknown>;
  if (typeof style.font !== "string") return false;

  for (const scene of c.scenes as Record<string, unknown>[]) {
    if (!scene.id || typeof scene.id !== "string") return false;
    if (!scene.templateId || typeof scene.templateId !== "string") return false;
    if (!scene.timing || typeof scene.timing !== "object") return false;
  }

  // Validate audio if present
  if (c.audio) {
    const audio = c.audio as Record<string, unknown>;
    if (typeof audio.trackId !== "string") return false;
    if (typeof audio.audioUrl !== "string") return false;
    if (typeof audio.duration !== "number") return false;
    if (!Array.isArray(audio.beatMarkers)) return false;
    if (!audio.beatDetection || typeof audio.beatDetection !== "object") return false;
  }

  return true;
}

// ─── Factory ───────────────────────────────────────────────────

export function createDefaultScene(overrides?: Partial<SceneConfig>): SceneConfig {
  return {
    id: crypto.randomUUID(),
    templateId: "media",
    variables: {
      texts: "",
      mediaUrl: "",
      mediaKeyword: "",
    },
    timing: { fixedDuration: 3 },
    ...overrides,
  };
}
